const webhookItem = $('Webhook').item;
let rawBody;
if (webhookItem.binary && webhookItem.binary.data) {
  rawBody = Buffer.from(webhookItem.binary.data.data, 'base64').toString('utf8');
} else {
  rawBody = JSON.stringify(webhookItem.json.body);
}
const headers = webhookItem.json.headers || {};
const signature = headers['didi-header-sign'] || headers['Didi-Header-Sign'] || '';

// 99Food usa inteiros 64-bit (app_id, order_id, event_id, shop_id, uid) que
// perdem precisao no JSON.parse padrao do JS (documentado pela propria 99Food,
// recomendam json-bigint). Protegemos citando esses campos como string via
// regex ANTES do parse, preservando os digitos exatos.
const protectedFields = ['app_id', 'order_id', 'event_id', 'shop_id', 'uid', 'apply_id'];
const pattern = new RegExp('"(' + protectedFields.join('|') + ')"\\s*:\\s*(-?\\d+)(?=[,}\\s])', 'g');
const safeBody = rawBody.replace(pattern, '"$1":"$2"');

let evento = {};
try { evento = JSON.parse(safeBody); } catch (e) { evento = {}; }

return [{
  json: {
    rawBody,
    signature,
    app_id: evento.app_id || null,
    app_shop_id: evento.app_shop_id || null,
    type: evento.type || null,
    timestamp: evento.timestamp || null,
    data: evento.data || {},
  },
}];

const parsed = $('Extrair corpo e assinatura').item.json;
const config = $('Buscar config pelo app_id').item.json;
const computed = $json.data ?? $json.hash ?? $json.hmac ?? $json.value ?? '';
const valido = String(computed).toLowerCase() === String(parsed.signature || '').toLowerCase();
return [{
  json: {
    ...parsed,
    empresa_id: config.empresa_id,
    app_id_valor: config.app_id_valor,
    app_shop_id_valor: config.app_shop_id_valor,
    api_secret: config.api_secret,
    assinatura_valida: valido,
  },
}];

const ctx = $('Switch por tipo de evento').item.json;
const empresaId = ctx.empresa_id;
const orderInfo = ctx.data.order_info || {};
const price = orderInfo.price || {};
const addr = orderInfo.receive_address || {};

// Mapa de pay_channel -> forma de pagamento PT-BR, melhor tentativa, nao
// confirmado ao vivo ainda - ver LEIA-ME.
const payChannelMap = {
  150: 'Cartão de Crédito', 153: 'Dinheiro', 154: 'Outros', 190: 'Outros', 120: 'Outros',
  212: 'Pix', 280: 'Pix', 257: 'Outros', 258: 'Outros', 259: 'Outros', 260: 'Outros',
  262: 'Cartão de Crédito', 263: 'Cartão de Débito', 264: 'Outros',
};
const tipoPagamento = payChannelMap[orderInfo.pay_channel] || 'Outros';
const statusPagamento = orderInfo.pay_method === 1 ? 'pago' : 'pendente';

// 99Food tem 2 modelos de price ativos, escolhidos por delivery_type
// (1=entrega pela 99Food -> Price Model 1, sem campo de total explicito;
// 2=entrega pela loja -> Price Model 2, com real_pay_price/customer_need_paying_money).
// Bug real encontrado 2026-08-06, antes de qualquer pedido real chegar:
// o codigo so tratava Model 2 - todo pedido com delivery_type=1 (que o
// usuario espera ser o modo liberado primeiro pela 99Food) cairia no
// fallback ?? 0 e gravaria valor_total=0. Model 1 nao tem campo de total
// documentado, entao o valor abaixo e DERIVADO (order_price - descontos +
// taxa de entrega original - reembolsos), nao confirmado ainda contra um
// pedido real - ver LEIA-ME.
const isModel2 = price.real_pay_price != null || price.customer_need_paying_money != null;
let valorProdutos, valorEntrega, desconto, valorTotal;
if (isModel2) {
  valorProdutos = (price.order_price || 0) / 100;
  valorEntrega = (price.delivery_price || 0) / 100;
  desconto = ((price.items_discount || 0) + (price.delivery_discount || 0)) / 100;
  valorTotal = (price.real_pay_price ?? price.customer_need_paying_money ?? 0) / 100;
} else {
  valorProdutos = ((price.order_price || 0) - (price.items_discount || 0)) / 100;
  valorEntrega = Math.max(0, (price.store_charged_delivery_price || 0) - (price.delivery_discount || 0)) / 100;
  desconto = ((price.items_discount || 0) + (price.delivery_discount || 0)) / 100;
  valorTotal = valorProdutos + valorEntrega + ((price.service_price || 0) + (price.meal_top_up_price || 0) - (price.refund_price || 0)) / 100;
}
const taxaServico = (price.others_fees?.service_price ?? price.service_price ?? 0) / 100;

// delivery_type: 1=entrega pela 99Food (courier da plataforma), 2=entrega
// pela loja - eixo diferente de fulfillment_mode (entrega vs retirada).
// Mesma convencao ja usada pro iFood (entregador_tipo='MERCHANT' quando a
// loja entrega) para manter os dois marketplaces comparaveis no dashboard.
const entregadorTipo = orderInfo.delivery_type === 1 ? '99FOOD' : 'MERCHANT';

const valorPendente = price.customer_need_paying_money ?? price.real_pay_price ?? valorTotal;
const changeFor = orderInfo.change_for || 0;
const troco = changeFor > valorPendente * 100 ? (changeFor - valorPendente * 100) / 100 : null;

// fulfillment_mode: 0=Delivery, 1=Self Pickup (retirada).
const tipoEntrega = orderInfo.fulfillment_mode === 1 ? 'TAKEOUT' : 'DELIVERY';

const remarkArr = Array.isArray(orderInfo.remark) ? orderInfo.remark : (orderInfo.remark ? [orderInfo.remark] : []);

return [{
  json: {
    empresa_id: empresaId,
    order_id: ctx.data.order_id,
    orderInfo,
    cliente: {
      nome: addr.name || 'Cliente 99Food',
      telefone: addr.phone || '',
      idExterno99food: addr.uid || null,
      cpf: addr.cpf || null,
      endereco: addr.street_name || '',
      numero: addr.street_number || addr.house_number || '',
      bairro: addr.district || '',
      cidade: addr.city || '',
      estado: addr.state || '',
      cep: addr.postal_code || '',
      complemento: addr.complement || null,
      latitude: addr.poi_lat ?? null,
      longitude: addr.poi_lng ?? null,
    },
    pagamento: { tipo_pagamento: tipoPagamento, status_pagamento: statusPagamento, troco },
    precos: {
      valor_produtos: valorProdutos,
      valor_entrega: valorEntrega,
      desconto,
      valor_total: valorTotal,
      taxa_servico_cliente: taxaServico,
      price_model: isModel2 ? 2 : 1,
      raw: price,
    },
    numero_exibicao: orderInfo.order_index != null ? String(orderInfo.order_index) : null,
    telefone_localizador: addr.locator || null,
    codigo_retirada_exibicao: orderInfo.handover_code || orderInfo.pickup_code || null,
    tipo_entrega_marketplace: tipoEntrega,
    entregador_tipo: entregadorTipo,
    observacoes: remarkArr.join(', '),
  },
}];

const found = $('Buscar cliente existente').item.json;
const cliente_id = found.id || $json.id;
return [{ json: { ...$('Preparar dados do pedido e cliente').item.json, cliente_id } }];

const ctx = $json;
const items = ctx.orderInfo.order_items || [];
return items.map(it => {
  const remark = Array.isArray(it.remark) ? it.remark.join(', ') : (it.remark || null);
  return {
    json: {
      empresa_id: ctx.empresa_id,
      cliente_id: ctx.cliente_id,
      order_id: ctx.order_id,
      orderInfo: ctx.orderInfo,
      pagamento: ctx.pagamento,
      precos: ctx.precos,
      numero_exibicao: ctx.numero_exibicao,
      telefone_localizador: ctx.telefone_localizador,
      codigo_retirada_exibicao: ctx.codigo_retirada_exibicao,
      tipo_entrega_marketplace: ctx.tipo_entrega_marketplace,
      entregador_tipo: ctx.entregador_tipo,
      observacoes: ctx.observacoes,
      item_externo_id: String(it.app_item_id),
      uniqueid_marketplace: it.mdu_id != null ? String(it.mdu_id) : null,
      nome_item: it.name,
      quantidade: it.amount,
      preco_unitario: (it.sku_price || 0) / 100,
      subtotal: (it.total_price ?? ((it.sku_price || 0) * (it.amount || 1))) / 100,
      observacao_cliente: remark,
    },
  };
});

const direct = $('Resolver produto_id').item.json.produto_id;
let produtoId = direct;
let naoCatalogado = false;
if (!produtoId) {
  naoCatalogado = true;
  const existing = $('Buscar placeholder existente').item.json.id;
  produtoId = existing || $json.id;
}
return [{ json: { ...$('Explodir itens do pedido').item.json, produto_id: produtoId, item_nao_catalogado: naoCatalogado } }];

const list = items.map(i => i.json);
const first = list[0] || {};
return [{
  json: {
    empresa_id: first.empresa_id,
    cliente_id: first.cliente_id,
    order_id: first.order_id,
    orderInfo: first.orderInfo,
    pagamento: first.pagamento,
    precos: first.precos,
    numero_exibicao: first.numero_exibicao,
    telefone_localizador: first.telefone_localizador,
    codigo_retirada_exibicao: first.codigo_retirada_exibicao,
    tipo_entrega_marketplace: first.tipo_entrega_marketplace,
    entregador_tipo: first.entregador_tipo,
    observacoes: first.observacoes,
    itens: list,
    algum_nao_catalogado: list.some(i => i.item_nao_catalogado),
  },
}];

const pedidoId = $json.id;
const itens = $('Agregar itens resolvidos').item.json.itens;
return itens.map(it => ({
  json: {
    pedido_id: pedidoId,
    produto_id: it.produto_id,
    quantidade: it.quantidade,
    preco_unitario: it.preco_unitario,
    subtotal: it.subtotal,
    uniqueid_marketplace: it.uniqueid_marketplace,
    observacao_cliente: it.observacao_cliente,
  },
}));

const cfg = $('Buscar config pelo app_id').item.json;
const store = $getWorkflowStaticData('global');
store.food99Tokens = store.food99Tokens || {};
const cached = store.food99Tokens[cfg.app_shop_id_valor];
const valido = !!(cached && cached.expiresAt > Date.now() + 60000);
return [{
  json: {
    app_id_valor: cfg.app_id_valor,
    app_shop_id_valor: cfg.app_shop_id_valor,
    api_secret: cfg.api_secret,
    auth_token: valido ? cached.authToken : null,
    token_valido: valido,
  },
}];

const ctx = $('Checar token em cache').item.json;
const resp = $json;
const tokenData = resp.data || {};
// So marca valido/cacheia se a chamada realmente teve sucesso (errno 0 E
// auth_token presente) - bug real encontrado ao vivo 2026-08-06: sem essa
// checagem, uma falha (ex: autorizacao da loja expirada, errno 10102)
// ainda marcava token_valido=true com auth_token undefined, e o erro real
// so aparecia depois, de forma confusa, na chamada de confirmacao.
const ok = resp.errno === 0 && !!tokenData.auth_token;
const store = $getWorkflowStaticData('global');
store.food99Tokens = store.food99Tokens || {};
if (ok) {
  store.food99Tokens[ctx.app_shop_id_valor] = {
    authToken: tokenData.auth_token,
    expiresAt: tokenData.token_expiration_time ? tokenData.token_expiration_time * 1000 : Date.now() + 21600000,
  };
}
return [{ json: { ...ctx, auth_token: ok ? tokenData.auth_token : null, token_valido: ok, token_erro: ok ? null : (resp.errmsg || 'erro desconhecido ao obter token') } }];

parameters.query:
select
  (select mp.pedido_id from marketplace_pedidos mp where mp.marketplace_order_id = $1 limit 1) as pedido_id,
  (select p.status from pedidos p join marketplace_pedidos mp on mp.pedido_id = p.id where mp.marketplace_order_id = $1 limit 1) as status;

