const evt = $('Switch por tipo de evento').item.json;
const pedidoId = $json.pedido_id;
const data = evt.data;
const isCancel = evt.type === 'orderCancelApply';
let payload;
if (isCancel) {
  payload = {
    tipo: 'cancelamento',
    mensagem: data.apply_reason || '',
    alternativas: { reason_list: data.reason_list || [] },
    // Store tem 5min pra responder (repetido a cada 2min como lembrete pela 99Food).
    prazo_minutos: 5,
  };
} else {
  payload = {
    tipo: 'reembolso',
    mensagem: data.apply_reason || '',
    alternativas: { base_reason_list: data.base_reason_list || [], images: data.images || [] },
    // Refund fica ate 25h em aberto (25 lembretes de 1h) antes do auto-aceite da 99Food.
    prazo_minutos: 25 * 60,
  };
}
return [{
  json: {
    pedido_id: pedidoId,
    marketplace_id: 'e11ec855-6936-410d-a56a-635adebfe595',
    disputa_id_externo: String(data.apply_id),
    tipo: payload.tipo,
    mensagem: payload.mensagem,
    alternativas: JSON.stringify(payload.alternativas),
    prazo_minutos: payload.prazo_minutos,
  },
}];
